package com.yigongbao.backup.cleanup;
import org.junit.jupiter.api.Test; import java.util.*; import static org.assertj.core.api.Assertions.*;
class CleanupServiceTest { @Test void onlyActiveMatchingPermitCanDelete(){List<String> deleted=new ArrayList<>(); CleanupClient c=new CleanupClient(){public Evaluation evaluate(CleanupRequest r){return new Evaluation("t",List.of("a"),1);} public Permit pollPermit(String t){return new Permit("p",t,List.of("a","b"),"ACTIVE");} public void delete(Permit p,String k){if(k.equals("b"))throw new RuntimeException("fail");deleted.add(k);}}; var s=new CleanupService(c); assertThat(s.dryRun(180).taskId()).isEqualTo("t"); var r=s.execute("t"); assertThat(r.deleted()).isEqualTo(1); assertThat(r.failedKeys()).containsExactly("b"); assertThat(deleted).containsExactly("a"); }
 @Test void usesLocalCosDeleterInsteadOfRemoteDeleteCommand(){List<String> deleted=new ArrayList<>(); CleanupClient c=new CleanupClient(){public Evaluation evaluate(CleanupRequest r){return null;} public Permit pollPermit(String t){return new Permit("p",t,List.of("a"),"ACTIVE");} public void delete(Permit p,String k){throw new AssertionError("remote delete must not be called");}}; com.yigongbao.backup.backup.CosObjectClient cos=new com.yigongbao.backup.backup.CosObjectClient(){public java.io.InputStream download(String k){return java.io.InputStream.nullInputStream();} public void delete(String k,CleanupClient.Permit p){deleted.add(k);}}; assertThat(new CleanupService(c,cos).execute("t").deleted()).isEqualTo(1); assertThat(deleted).containsExactly("a"); }
 @Test void rejectsRevokedPermit(){CleanupClient c=new CleanupClient(){public Evaluation evaluate(CleanupRequest r){return null;} public Permit pollPermit(String t){return new Permit("p",t,List.of("a"),"REVOKED");} public void delete(Permit p,String k){}}; assertThatThrownBy(()->new CleanupService(c).execute("t")).isInstanceOf(IllegalStateException.class); }
 @Test void rejectsPermitWhoseKeysDifferFromFrozenTaskItems(){CleanupClient c=new CleanupClient(){public Evaluation evaluate(CleanupRequest r){return null;} public Permit pollPermit(String t){return new Permit("p",t,List.of("a","unexpected"),"ACTIVE");} public void delete(Permit p,String k){throw new AssertionError("must not delete");}}; CleanupTaskService tasks=org.mockito.Mockito.mock(CleanupTaskService.class); CleanupTaskEntity task=new CleanupTaskEntity();task.setId(7L);task.setTaskNo("t");org.mockito.Mockito.when(tasks.findByTaskNo("t")).thenReturn(task);org.mockito.Mockito.doThrow(new IllegalStateException("对象集合不匹配")).when(tasks).validatePermitObjectSet(org.mockito.ArgumentMatchers.eq(7L),org.mockito.ArgumentMatchers.anyList(),org.mockito.ArgumentMatchers.isNull());assertThatThrownBy(()->new CleanupService(c,null,tasks).execute("t")).isInstanceOf(IllegalStateException.class).hasMessageContaining("对象集合");org.mockito.Mockito.verify(tasks).validatePermitObjectSet(org.mockito.ArgumentMatchers.eq(7L),org.mockito.ArgumentMatchers.anyList(),org.mockito.ArgumentMatchers.isNull());}
 @Test void leaseLossStopsDeletionWithoutMutatingItemEvidence(){List<String> deleted=new ArrayList<>();CleanupClient c=new CleanupClient(){public Evaluation evaluate(CleanupRequest r){return null;}public Permit pollPermit(String t){return new Permit("p",t,List.of("a"),"ACTIVE");}public void delete(Permit p,String k){deleted.add(k);}};CleanupTaskService tasks=org.mockito.Mockito.mock(CleanupTaskService.class);CleanupTaskEntity task=new CleanupTaskEntity();task.setId(7L);task.setTaskNo("t");DeletePermitEntity permit=new DeletePermitEntity();permit.setId(11L);permit.setStatus("ISSUED");DeletePermitEntity claimed=new DeletePermitEntity();claimed.setId(11L);claimed.setStatus("CLAIMED");claimed.setLocalFencingToken(4L);org.mockito.Mockito.when(tasks.findByTaskNo("t")).thenReturn(task);org.mockito.Mockito.when(tasks.savePermit(org.mockito.ArgumentMatchers.eq(7L),org.mockito.ArgumentMatchers.any(),org.mockito.ArgumentMatchers.isNull(),org.mockito.ArgumentMatchers.eq(0L))).thenReturn(permit);org.mockito.Mockito.when(tasks.claimPermit(org.mockito.ArgumentMatchers.eq(11L),org.mockito.ArgumentMatchers.anyString(),org.mockito.ArgumentMatchers.any())).thenReturn(claimed);org.mockito.Mockito.doThrow(new IllegalStateException("permit 租约失效")).when(tasks).renewPermitLease(org.mockito.ArgumentMatchers.eq(11L),org.mockito.ArgumentMatchers.anyString(),org.mockito.ArgumentMatchers.eq(4L),org.mockito.ArgumentMatchers.any());assertThatThrownBy(()->new CleanupService(c,null,tasks).execute("t")).isInstanceOf(IllegalStateException.class).hasMessageContaining("租约");assertThat(deleted).isEmpty();org.mockito.Mockito.verify(tasks,org.mockito.Mockito.never()).markItem(org.mockito.ArgumentMatchers.anyString(),org.mockito.ArgumentMatchers.anyString(),org.mockito.ArgumentMatchers.anyString(),org.mockito.ArgumentMatchers.any(),org.mockito.ArgumentMatchers.anyLong());}
 @Test void rejectsPermitWhenLocalFrozenTaskDoesNotExist(){CleanupClient c=new CleanupClient(){public Evaluation evaluate(CleanupRequest r){return null;}public Permit pollPermit(String t){return new Permit("p",t,List.of("a"),"ACTIVE");}public void delete(Permit p,String k){throw new AssertionError("must not delete");}};CleanupTaskService tasks=org.mockito.Mockito.mock(CleanupTaskService.class);assertThatThrownBy(()->new CleanupService(c,null,tasks).execute("missing")).isInstanceOf(IllegalStateException.class).hasMessageContaining("冻结清理任务");}
}
